int getbit(int n, int k) { return (n >> k) & 1; }
void onbit(int &n, int k) { n = n | (1 << k); }
void offbit(int &n, int k) { n = n & ~(1 << k); }
int main()
{
    int n = 10;
    cout << getbit(n, 1) << getbit(n, 2) << " ";
    onbit(n, 0);
    offbit(n, 3);
    cout << n << endl;
    return 0;
}

