#include <iostream>
#include <algorithm>
#include <cstdlib>
#include <bitset>
using namespace std;
int nextComb(int a[], int n, int k)
{
    int i = k - 1;
    while (i >= 0 && a[i] == n - k + i + 1) i--;
    if (i < 0) return 0;
    a[i]++;
    for (int j = i + 1; j < k; j++) a[j] = a[j - 1] + 1;
    return 1;
}
int main()
{
    int a[3] = {1, 2, 3};
    for (int t = 0; t < 6; t++) nextComb(a, 5, 3);
    for (int i = 0; i < 3; i++) cout << a[i];
    cout << endl;
    return 0;
}

